<article class="product-card"><a href="{{ route('product', $product) }}"><img src="{{ $product->image }}" alt="{{ $product->name }}"><div class="product-info"><small>{{ $product->brand }}</small><h3>{{ $product->name }}</h3><p>{{ $product->subtitle }}</p><strong>{{ toman($product->price) }}</strong></div></a><button onclick="addProduct({{ $product->id }}, '{{ addslashes($product->name) }}', '{{ $product->image }}', {{ $product->variants->first()->volume_ml ?? 35 }}, {{ $product->price }})">افزودن به سبد</button></article>
